"""Freeze an unchanged-generator confirmation on new scenarios."""
from pathlib import Path
from datetime import datetime,timezone
import json,hashlib,shutil
H=Path(__file__).resolve().parent;N=H.parent/'softplay_style_confirmation_20260910'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
    result=json.loads((H/'summary.json').read_text());assert result['both_development_realism_gates_passed'];N.mkdir(exist_ok=False);d=N/'fresh';d.mkdir();src=H/'b0_style';pp=json.loads((src/'pilot-plan.json').read_text())
