    pp['pools']=[{**s,'pool_id':832+i,'scenario':i,'seed':1200559+997*i} for i,s in enumerate(pp['pools'])];pp['created_at']=datetime.now(timezone.utc).isoformat();pp.pop('paired_existing_control',None);pp.pop('counterfactual_development_replay',None);pp['fresh_seed_confirmation']=True;pp['unchanged_source_plan_sha256']=sha(src/'pilot-plan.json');(d/'pilot-plan.json').write_text(json.dumps(pp,indent=2))
    for name in ['controller.joblib','soft_controller.py','conditional_action_features.py','advanced_features.py','causal_styles.py','audit_batch.py','replay_batch.py','prepare_features.py','run_generation.py','run_analysis.py','causal-style-tests.json']:shutil.copy2(H/name,N/name)
