    plan={'created_at':datetime.now(timezone.utc).isoformat(),'generator_arms':['fresh'],'generator_plan_sha256':{'fresh':sha(d/'pilot-plan.json')},'parent_development_sha256':sha(H/'summary.json'),'controller_sha256':sha(d/'controller.joblib'),'all_generator_model_environment_bytes_unchanged':True,'pools':32,'hands_per_pool':3000,'seed_formula':'1200559+997*i','pool_ids':'832..863','realism_gate':'Unchanged source AUC<=.85, preflop call rate and call-strength gaps<=.05, >=12 supported targets, all4 ordinary families, legal/causal audits. No retuning or replacement seeds if it fails.','progression':'Only a passing confirmation allows one frozen detector-utility study comparing original-only, multiple fixed resampling controls, and the three style populations across model seeds. No outer-held access in this confirmation.','protected':json.loads((H/'study-plan.json').read_text())['protected']};(N/'study-plan.json').write_text(json.dumps(plan,indent=2));print(json.dumps({'directory':str(N),'plan_sha256':sha(N/'study-plan.json'),'unchanged_controller':plan['controller_sha256']}))
